import type { Meta, StoryObj } from '@storybook/react-vite';

import CopyButton from '.';

const meta: Meta<typeof CopyButton> = {
    component: CopyButton,
    title: 'CopyButton',
};

export default meta;
type Story = StoryObj<typeof CopyButton>;

export const Primary: Story = {
    parameters: {
        nextjs: {
            appDirectory: true,
        },
    },
    render: () => (
        <div style={{ padding: '1rem' }}>
            <CopyButton
                copyLabel={'Kopier'}
                copiedLabel={'Kopiert!'}
                copyOnClick={'Tekst å kopiere'}
            />
        </div>
    ),
};

'use client';

import { useState } from 'react';
import { Button, type ButtonProps, Tooltip } from '@digdir/designsystemet-react';
import { FilesIcon, CheckmarkCircleFillIcon } from '@navikt/aksel-icons';
import HStack from '../hstack';

type CopyButtonProps = {
    copyLabel: string;
    copiedLabel: string;
    copyOnClick: string;
} & ButtonProps & React.HTMLAttributes<HTMLButtonElement>;

const CopyButton = ({ copyLabel, copiedLabel, copyOnClick, ...props }: CopyButtonProps) => {
    const [clicked, setClicked] = useState(false);

    const copyToClipboard = (text: string) => {
        setClicked(true);
        navigator.clipboard.writeText(text);
    };

    return (
        <Tooltip
            // @ts-expect-error: ignore complaint that Element cannot be set as content
            content={
                clicked ? (
                    <HStack>
                        <CheckmarkCircleFillIcon
                            color='#D1F4E1'
                            fontSize='1.2em'
                        />
                        {copiedLabel}
                    </HStack>
                ) : (
                    copyLabel
                )
            }
            placement='top'
        >
            <Button
                data-size='sm'
                variant='secondary'
                onClick={() => copyToClipboard(copyOnClick)}
                onMouseOver={() => setClicked(false)}
                {...props}
            >
                <FilesIcon aria-hidden />
                <span className={'sr-only'}>{copyLabel}</span>
            </Button>
        </Tooltip>
    );
};

export default CopyButton;

import React from 'react';
import cn from 'classnames';

import styles from './hstack.module.scss';

const HStack = ({ children, className, ...props }: React.HTMLAttributes<HTMLDivElement>) => {
    return (
        <div
            className={cn(styles.wrapper, className)}
            {...props}
        >
            {children}
        </div>
    );
};

export default HStack;

